const calEvents = $('Get Next 48h Calendar Events').all().map(i => i.json);
const logItems = $('Read Event Log').all().map(i => i.json);
const reminders = $('Read Reminders').all().map(i => i.json);

const now = new Date();
const today = now.toISOString().split('T')[0];
const tomorrow = new Date(Date.now() + 86400000).toISOString().split('T')[0];

// 1. REMINDERS: Find events happening today/tomorrow that need prep reminders
const upcomingEvents = calEvents.filter(e => {
  const eventDate = (e.start?.dateTime || e.start?.date || '').substring(0, 10);
  return eventDate === today || eventDate === tomorrow;
}).map(e => {
  const start = e.start?.dateTime ? new Date(e.start.dateTime) : null;
  const hoursUntil = start ? (start.getTime() - now.getTime()) / 3600000 : null;
  return {
    title: e.summary || 'Untitled',
    date: (e.start?.dateTime || e.start?.date || '').substring(0, 10),
    time: start ? start.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }) : 'All day',
    location: e.location || '',
    hoursUntil: hoursUntil ? Math.round(hoursUntil * 10) / 10 : null
  };
});

// 2. SCHEDULE CONFLICTS: Check for overlapping events
const timedEvents = calEvents.filter(e => e.start?.dateTime && e.end?.dateTime);
const conflicts = [];
for (let i = 0; i < timedEvents.length; i++) {
  for (let j = i + 1; j < timedEvents.length; j++) {
    const a = timedEvents[i];
    const b = timedEvents[j];
    const aStart = new Date(a.start.dateTime).getTime();
    const aEnd = new Date(a.end.dateTime).getTime();
    const bStart = new Date(b.start.dateTime).getTime();
    const bEnd = new Date(b.end.dateTime).getTime();
    if (aStart < bEnd && bStart < aEnd) {
      conflicts.push({
        event1: a.summary || 'Untitled',
        event2: b.summary || 'Untitled',
        time1: new Date(a.start.dateTime).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }),
        time2: new Date(b.start.dateTime).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' })
      });
    }
  }
}

// 3. PENDING ACTION ITEMS: From event log in last 48h with no resolution
const twoDaysAgo = new Date(Date.now() - 2 * 86400000).toISOString();
const pendingActions = logItems.filter(item =>
  item.timestamp > twoDaysAgo &&
  item.has_action_item === 'true' &&
  item.action_item
);

// 4. PENDING REMINDERS: Reminders that are still pending
const pendingReminders = reminders.filter(r =>
  r.status === 'pending' &&
  r.scheduled_for
);

// Build the proactive outreach prompt
const promptData = {
  today: now.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' }),
  upcomingEvents,
  conflicts,
  pendingActions,
  pendingReminders
};

// Determine if there's anything worth sending
const hasContent = conflicts.length > 0 || pendingActions.length > 0 ||
  upcomingEvents.some(e => e.hoursUntil !== null && e.hoursUntil > 0 && e.hoursUntil <= 3);

const prompt = `You are LifeSync, a proactive family life assistant. Analyze the following and create a short, helpful text message ONLY if there is something actionable or important. If nothing needs attention, respond with exactly "NO_OUTREACH_NEEDED".

Context: Parent managing family with co-parent Josh, daughter Emma at St. Patrick School.
Today: ${promptData.today}

Upcoming Events (next 48h):
${JSON.stringify(promptData.upcomingEvents, null, 2)}

Schedule Conflicts Detected:
${conflicts.length > 0 ? JSON.stringify(conflicts, null, 2) : 'None'}

Pending Action Items (unresolved from last 48h):
${pendingActions.length > 0 ? pendingActions.map(a => `- [${a.source}] ${a.action_item} (from: ${a.from || a.subject})`).join('\n') : 'None'}

Pending Reminders:
${pendingReminders.length > 0 ? pendingReminders.map(r => `- ${r.message} (scheduled: ${r.scheduled_for})`).join('\n') : 'None'}

Rules:
- Events within 3 hours: Send a heads-up with time and location
- Schedule conflicts: ALWAYS alert, this is high priority
- Pending actions older than 24h: Gentle nudge to address them
- Keep the message SHORT and texting-style (under 400 chars)
- Use emojis sparingly
- Be warm but direct
- Start with a context label like "Heads up" or "Reminder" or "Conflict alert"`;

return [{ json: { prompt, hasContent, promptData } }];

const calEvents = $('Get Next Week Calendar Events').all().map(i => i.json);

const eventsByDay = {};
const dayNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

calEvents.forEach(e => {
  const dateStr = (e.start?.dateTime || e.start?.date || '').substring(0, 10);
  const day = new Date(dateStr + 'T12:00:00').getDay();
  const dayLabel = dayNames[day];
  if (!eventsByDay[dayLabel]) eventsByDay[dayLabel] = [];
  const time = e.start?.dateTime
    ? new Date(e.start.dateTime).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' })
    : 'All day';
  eventsByDay[dayLabel].push(`${time}: ${e.summary || 'Untitled'}`);
});

let weekSummary = '';
for (const day of dayNames) {
  if (eventsByDay[day]) {
    weekSummary += `${day}:\n${eventsByDay[day].map(e => `  - ${e}`).join('\n')}\n`;
  }
}

if (!weekSummary) weekSummary = 'No events scheduled.';

const prompt = `You are LifeSync. Create a brief, friendly Sunday evening "week ahead" preview text message for a busy parent. Keep it under 600 characters, highlight the busiest days, mention any potential conflicts, and note anything that might need prep (school events, appointments, etc).

Upcoming Week:
${weekSummary}

Start with something like "Week ahead" and keep it casual/texting style with a few emojis.`;

return [{ json: { prompt } }];

const logItems = $('Read Evening Event Log').all().map(i => i.json);

const now = new Date();
const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate()).toISOString();

// Find action items from today that are still unresolved
const todayActions = logItems.filter(item =>
  item.timestamp >= todayStart &&
  item.has_action_item === 'true' &&
  item.action_item
);

// Find items from previous days that are still pending (older than 24h)
const olderCutoff = new Date(Date.now() - 86400000).toISOString();
const overdueActions = logItems.filter(item =>
  item.timestamp < olderCutoff &&
  item.has_action_item === 'true' &&
  item.action_item
).slice(-5); // Last 5 overdue items max

const hasFollowUps = todayActions.length > 0 || overdueActions.length > 0;

let prompt = '';
if (hasFollowUps) {
  prompt = `You are LifeSync doing an evening check-in. Create a brief, friendly text message reminding the parent about unfinished items. Be gentle, not naggy. Keep under 400 characters.

Today's Unfinished Action Items:
${todayActions.length > 0 ? todayActions.map(a => `- [${a.source}] ${a.action_item}`).join('\n') : 'None'}

Overdue Items (from earlier):
${overdueActions.length > 0 ? overdueActions.map(a => `- [${a.source}] ${a.action_item} (from ${a.from || a.subject})`).join('\n') : 'None'}

If nothing important is pending, respond with "NO_OUTREACH_NEEDED". Only send if there are genuinely important items the parent should handle. Start with something like "Evening check-in" and keep it warm.`;
} else {
  prompt = 'NO_OUTREACH_NEEDED';
}

return [{ json: { prompt, hasFollowUps } }];

const body = $input.item.json.body;
const alertType = body.type || 'general';
const details = body.details || {};
const source = body.source || 'unknown';

const typeLabels = {
  conflict: 'Schedule Conflict',
  urgent: 'Urgent Alert',
  deadline: 'Deadline Approaching',
  rsvp_needed: 'RSVP Needed',
  pickup_change: 'Pickup Change',
  cancellation: 'Cancellation'
};

const prompt = `You are LifeSync sending a REAL-TIME alert to a busy parent. This is time-sensitive. Create a short, clear text message (under 300 chars).

Alert Type: ${typeLabels[alertType] || alertType}
Source: ${source}
Details: ${JSON.stringify(details)}

Be direct and clear. Start with an appropriate emoji and the alert type. Include the key details and any immediate action needed.`;

return [{ json: { prompt, alertType, details, source } }];
